<script setup>
import { ref,computed } from 'vue'
import { useRouter } from 'vue-router'
import { Wallet,CalendarDays,ClipboardCheck,ThumbsUp,MessageCircle,Clock3 } from 'lucide-vue-next'
import PageTitle from '../components/PageTitle.vue'
import StatusBadge from '../components/StatusBadge.vue'
import OrderAction from '../components/OrderAction.vue'
import { state,money,income,imageOf } from '../lib/store'
import { requireRole,notify } from '../lib/actions'
const router=useRouter(),tab=ref('全部'),visible=computed(()=>state.orders.filter(o=>tab.value==='全部'||o.status===tab.value))
function remind(o){if(!requireRole(router,'creator')||o.reminded)return;o.reminded=true;notify('已保存演示催验收记录，每单限 1 次')}
</script>
<template><div><PageTitle title="我的订单" description="把每一份灵感，交付成作品。"/><div class="stat-grid"><section class="stat-card" v-for="s in [{label:'累计收入',value:'¥'+money(state.earned),icon:Wallet,money:true},{label:'本月入账',value:'¥'+money(state.flows.filter(f=>f.type==='分账入账').reduce((s,f)=>s+f.cents,0)),icon:CalendarDays,money:true},{label:'累计成单',value:state.orders.length,icon:ClipboardCheck},{label:'好评率',value:'98%',icon:ThumbsUp}]" :key="s.label"><div class="stat-icon"><component :is="s.icon" :size="25"/></div><div><label>{{s.label}}</label><strong :class="{'price-text':s.money}">{{s.value}}</strong></div></section></div><el-tabs v-model="tab"><el-tab-pane v-for="s in ['全部','待交付','待验收','已完成','纠纷中']" :key="s" :name="s" :label="s==='全部'?s:`${s} ${state.orders.filter(o=>o.status===s).length}`"/></el-tabs><div class="order-list"><article v-for="o in visible" :key="o.id" class="panel order-row"><img :src="imageOf(o.art)" :alt="o.title"/><div class="order-info"><h3><RouterLink :to="`/creator/orders/${o.id}`">{{o.title}}</RouterLink></h3><div class="tag-row"><span class="plain-tag">{{o.category}}</span><span class="plain-tag">{{o.mode}}</span></div><p>订单编号：{{o.id}}</p><p>下单时间：{{o.created}}</p></div><div class="order-progress"><div><StatusBadge :status="o.status"/><span v-if="o.status==='待交付'" :class="['order-deadline',{'price-text':o.hours<12}]"><Clock3 :size="14"/>剩余 {{o.hours}} 小时</span><span v-else-if="o.status==='待验收'" class="muted small">{{o.hours}} 小时后自动验收</span></div><div class="mini-timeline"><div v-for="(s,i) in ['已接单','创作中','待验收','已完成']" :key="s" :class="{done:i<=(o.status==='已完成'?3:o.status==='待验收'?2:1)}"><i/>{{s}}</div></div></div><div class="order-price"><span>任务赏金</span><strong class="price-text">¥{{money(o.cents)}}</strong><span>预计实得</span><strong class="price-text">¥{{money(income(o.cents))}}</strong></div><div class="order-buttons"><el-button type="primary" v-if="o.status==='待交付'" @click="router.push(`/creator/orders/${o.id}`)">去交付</el-button><el-button type="primary" v-else-if="o.status==='待验收'" :disabled="o.reminded" @click="remind(o)">{{o.reminded?'已催验收':'催验收'}}</el-button><el-button v-else @click="router.push(`/creator/orders/${o.id}`)">查看订单</el-button><OrderAction v-if="o.status==='已完成'" :order="o" kind="review"/><OrderAction v-else-if="o.status==='待交付'&&o.hours<12" :order="o" kind="extend"/><el-button v-else @click="router.push('/messages?chat=merchant')"><MessageCircle/>联系商家</el-button></div></article><el-empty v-if="!visible.length" description="这个状态下还没有订单"><el-button type="primary" @click="router.push('/tasks')">去任务广场看看</el-button></el-empty></div></div></template>
<style scoped>.order-list{display:grid;gap:14px}.order-row{display:grid;grid-template-columns:165px minmax(180px,1.3fr) minmax(190px,1fr) 115px 125px;gap:18px;align-items:center;margin:0!important;padding:15px}.order-row>img{width:100%;height:116px;object-fit:cover;object-position:left;border-radius:6px}.order-info h3{font-size:15px;margin:0 0 8px}.order-info p{font-size:10px;color:#87909f;margin:5px 0 0;overflow-wrap:anywhere}.order-progress>div:first-child{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.order-deadline{display:flex;gap:5px;align-items:center;font-size:11px}.order-price{border-left:1px solid #e3e7ef;padding-left:18px;display:grid;gap:2px;font-size:11px}.order-price strong{font-size:17px}.order-price span:nth-last-child(2){margin-top:6px}.order-buttons{display:grid;gap:10px}.order-buttons .el-button{font-size:12px;padding:8px 10px}.mini-timeline{display:flex;justify-content:space-between;font-size:9px;color:#8b93a3;margin-top:20px}.mini-timeline>div{display:flex;flex-direction:column;align-items:center;gap:6px;position:relative;flex:1}.mini-timeline i{width:13px;height:13px;border:2px solid #bdc6d8;border-radius:50%;background:#fff;z-index:1}.mini-timeline>div:after{content:'';position:absolute;height:2px;background:#d4dbe8;top:5px;left:50%;width:100%}.mini-timeline>div:last-child:after{display:none}.mini-timeline .done i{background:#002bd7;border-color:#002bd7}.mini-timeline .done:after{background:#002bd7}.mini-timeline .done{color:#303b53}@media(max-width:1350px){.order-row{grid-template-columns:130px minmax(150px,1fr) 110px 120px;gap:14px}.order-progress{grid-column:2;grid-row:2}.order-row>img{grid-row:1/3;height:142px}.order-price,.order-buttons{grid-row:1/3}.order-price{grid-column:3}.order-buttons{grid-column:4}.mini-timeline{margin-top:10px}.order-info p{font-size:9px}.order-info h3{font-size:14px}}@media(max-width:950px){.order-row{grid-template-columns:100px minmax(150px,1fr);gap:12px}.order-price{grid-column:1;grid-row:3;padding:0;border:0;grid-template-columns:1fr 1fr;align-items:center}.order-price span:nth-last-child(2){margin:0}.order-buttons{grid-column:2;grid-row:3;display:flex;flex-wrap:wrap}.order-row>img{height:130px}.order-progress{grid-column:2;grid-row:2}.order-info p{font-size:10px}.order-price strong{font-size:13px}}@media(max-width:650px){.order-row{grid-template-columns:83px minmax(0,1fr)}.order-row>img{height:115px}.order-buttons .el-button{font-size:11px;padding:8px}.order-price{grid-template-columns:1fr}.order-price span{font-size:9px}.order-info h3{font-size:13px}.order-info .plain-tag{font-size:9px}}
</style>
